mapper.select:
SELECT E.EMP_ID, E.EMP_NM, D.DEPT_NM, JG.JOB_GRD_NM, JP.JOB_PSTN_NM,
CASE WHEN E.PRFL_IMG_FILE_ID IS NOT NULL THEN '/api/files/images/' || E.PRFL_IMG_FILE_ID END AS PROFILE_IMAGE_URL FROM TB_EMPLOYEE E LEFT JOIN TB_DEPARTMENT D ON D.DEPT_CD = E.DEPT_CD LEFT JOIN TB_JOB_GRADE JG ON JG.JOB_GRD_CD = E.JOB_GRD_CD LEFT JOIN TB_JOB_POSITION JP ON JP.JOB_PSTN_CD = E.JOB_PSTN_CD WHERE E.ENABLED = 'Y'
AND E.EMP_ID <> #{excludeEmpId}
AND ( E.EMP_NM LIKE '%' || #{keyword} || '%' OR D.DEPT_NM LIKE '%' || #{keyword} || '%' OR JG.JOB_GRD_NM LIKE '%' || #{keyword} || '%' )
AND E.DEPT_CD = #{deptCd}
AND E.DEPT_CD = #{fixedDeptCd}
AND E.EMP_ID IN ( SELECT EMP_ID FROM TB_PROJ_MEMBER WHERE PROJ_ID = #{projId} )
ORDER BY D.DEPT_NM ASC, E.EMP_NM ASC FETCH FIRST 50 ROWS ONLY
